/**
 * Contracts for the connection and explorer endpoints (`/api/connections/...`).
 *
 * SECURITY: nothing here carries a password. A connection is identified by an
 * opaque `id` generated by the server; the browser never receives credentials.
 */
import { z } from "zod";
import {
  columnInfoSchema,
  constraintInfoSchema,
  indexInfoSchema,
  relationshipInfoSchema,
  schemaInfoSchema,
  tableInfoSchema,
} from "./metadata.js";
import { postgresConnectionSummarySchema } from "./postgres-connection.js";

/** The server's connection identifiers: unguessable URL-safe tokens. */
export const connectionIdSchema = z.string().regex(/^[A-Za-z0-9_-]{16,64}$/);

/** A schema or table name from a URL or query string. Bounded; the database does the real matching. */
export const identifierSchema = z.string().min(1).max(255);

/** Query string of the endpoints that need a schema (`?schema=public`). */
export const schemaQuerySchema = z.object({ schema: identifierSchema });

/** A saved connection as the browser sees it: everything except the password. */
export const connectionSummarySchema = postgresConnectionSummarySchema.extend({
  id: connectionIdSchema,
  provider: z.literal("postgresql"),
});
export type ConnectionSummary = z.infer<typeof connectionSummarySchema>;

// --- Responses -------------------------------------------------------------

/** Generic "it worked" answer (test connection, disconnect). */
export const okResponseSchema = z.object({ ok: z.literal(true) });

export const connectionResponseSchema = z.object({ connection: connectionSummarySchema });
export type ConnectionResponse = z.infer<typeof connectionResponseSchema>;

export const listConnectionsResponseSchema = z.object({
  connections: z.array(connectionSummarySchema),
});
export type ListConnectionsResponse = z.infer<typeof listConnectionsResponseSchema>;

export const schemasResponseSchema = z.object({ schemas: z.array(schemaInfoSchema) });
export const tablesResponseSchema = z.object({ tables: z.array(tableInfoSchema) });

/** Everything the table detail panel shows, fetched in one round trip. */
export const tableDetailsResponseSchema = z.object({
  columns: z.array(columnInfoSchema),
  constraints: z.array(constraintInfoSchema),
  indexes: z.array(indexInfoSchema),
});

export const relationshipsResponseSchema = z.object({
  relationships: z.array(relationshipInfoSchema),
});
